-- =====================================================================
-- استيراد خطة التحسين 1448هـ مباشرة (بديل زر «استيراد خطة 1448هـ» حتى يُنشر إصلاحه):
-- تقرير التقويم الذاتي بنسبه إن لم يوجد، ونسخة الخطة إن لم توجد، ثم البرامج الـ23 وإجراءات
-- الاستدامة الـ24 فيها دون تكرار ما أُدخل، ثم تُعتمد نسخةً سارية. تكرار التنفيذ آمن.
-- =====================================================================

insert into public.acc_reports (kind, academic_year, title, scores)
select 'self', coalesce((select value from public.settings where key = 'active_year'), '1448'), 'تقرير التقويم الذاتي 1448هـ', '{"1-1-1-1":75.25,"1-1-1-2":79.25,"1-2-1-1":85.5,"1-2-1-2":87.25,"1-2-1-3":88,"1-2-1-4":78.25,"1-2-1-5":68.5,"1-3-1-1":84.75,"1-3-1-2":73.25,"1-3-1-3":75,"1-4-1-1":66.5,"1-4-1-2":78.75,"1-4-1-3":89,"1-4-1-4":95,"1-5-1-1":82,"1-5-1-2":82.75,"2-1-1-1":71.5,"2-1-1-2":78.5,"2-1-1-3":78.25,"2-1-1-4":77.25,"2-1-1-5":65.5,"2-1-1-6":74,"2-1-1-7":72.5,"2-1-1-8":77.5,"2-1-1-9":75.25,"2-2-1-1":79.5,"2-2-1-2":79.5,"2-2-1-3":83.75,"2-2-1-4":81.5,"3-1-1-1":71.83,"3-1-1-2":73.6,"3-2-1-1":93.5,"3-2-1-2":79.25,"3-2-1-3":79.5,"3-2-1-4":72.75,"3-2-1-5":77.5,"3-2-1-6":75.5,"3-2-1-7":93.75,"4-1-1-1":55.75,"4-1-1-2":53.25,"4-1-1-3":57,"4-1-1-4":53.25,"4-2-1-1":63.5,"4-2-1-2":74,"4-2-1-3":78.75,"_overall":75}'::jsonb
where not exists (select 1 from public.acc_reports where kind = 'self' and academic_year = coalesce((select value from public.settings where key = 'active_year'), '1448'));

insert into public.acc_plans (academic_year, version, title, source, report_id, milestones)
select coalesce((select value from public.settings where key = 'active_year'), '1448'), 1, 'خطة التحسين والتطوير 1448هـ', 'self',
       (select id from public.acc_reports where kind = 'self' and academic_year = coalesce((select value from public.settings where key = 'active_year'), '1448') order by created_at limit 1), '[{"title":"مراجعة أولى لنسب الإنجاز","due":"نهاية الفصل الدراسي الأول","owner":"فريق التقويم الذاتي"},{"title":"تحديث الخطة ومعالجة التعثر","due":"بداية الفصل الدراسي الثاني","owner":"مدير المدرسة"},{"title":"قياس نواتج المبادرات والبرامج","due":"نهاية الفصل الدراسي الثاني","owner":"فريق التقويم الذاتي"},{"title":"رفع الخطة المحدثة على منصة تميز","due":"وفق الخطة الزمنية للهيئة","owner":"مدير المدرسة"}]'::jsonb
where not exists (select 1 from public.acc_plans where academic_year = coalesce((select value from public.settings where key = 'active_year'), '1448') and status <> 'archived');

insert into public.acc_programs (plan_id, kind, code, current, target, semester, team, initiative, methods, evidence, follow, period, measure, needs, rec, owner, sort)
select (select id from public.acc_plans where academic_year = coalesce((select value from public.settings where key = 'active_year'), '1448') and status <> 'archived' order by version desc, created_at desc limit 1), v.* from (values
('plan','1-2-1-5',68.5,75,'الفصل الدراسي الأول والثاني',array['المدير / الوكيل','المعلمون','الموجه الطلابي']::text[],'برنامج الموهبة والأنشطة الإثرائية','[{"t":"تنفيذ مسح مبكر لميول المتعلمين ومواهبهم"},{"t":"تنظيم أندية إثرائية أسبوعية متنوعة المجالات"},{"t":"إقامة مشاريع صغيرة تنمّي مهارات المستقبل"},{"t":"إشراك الأسرة في دعم المواهب المنزلية"},{"t":"توثيق منجزات المتعلمين بملفات إنجاز دورية"}]'::jsonb,array['خطة الأندية الإثرائية وجداول التنفيذ المعتمدة','سجلات المشاركة وملفات إنجاز المتعلمين','تقارير مشاريع/فعاليات موهبة وصور موثقة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','رصد مواهب 100% من المتعلمين، ومشاركة ≥ 15% منهم في مسابقات أو برامج إثرائية موثقة.',null,'المؤشر في مستوى الانطلاق (68.5%) والمستهدف 75% (التقدم). توقعات الهيئة: أساليب للكشف عن مواهب المتعلمين وقدراتهم وتحديد احتياجاتهم، وأنشطة إثرائية مرتبطة بنتائج التقويم، وتحفيز للمشاركة في المسابقات ودعم التميز فيها.',null,0),
('plan','1-3-1-1',84.75,90,'الفصل الدراسي الثاني — متابعة وتطوير',array['المدير / الوكيل','المعلمون','رائد النشاط']::text[],'برنامج العلاقات الإيجابية والتعاون المدرسي','[{"t":"تنفيذ أنشطة تعاونية أسبوعية داخل الصفوف"},{"t":"تفعيل مبادرات «الزميل المساند» بين المتعلمين"},{"t":"تدريب مهارات الحوار واحترام الاختلاف يوميًا"},{"t":"تنظيم فعاليات مشتركة تعزز الانتماء المدرسي"},{"t":"متابعة السلوك الاجتماعي بخطط دعم قصيرة"}]'::jsonb,array['خطط الأنشطة التعاونية وسجلات التنفيذ','سجلات ملاحظة للسلوك الاجتماعي الإيجابي','تقارير فعاليات مشتركة وصور/عينات أعمال']::text[],'فريق التقويم الذاتي','الفصل الدراسي الثاني — متابعة وتطوير','تنفيذ فعالية/لقاء تعزيزي شهريًا، ورضا المنسوبين عن مناخ العمل ≥ 85% في الاستبانة الداخلية.',null,'المؤشر في مستوى التقدم (84.75%) ويُستكمل التطوير للوصول إلى التميز (90%). توقعات الهيئة: مهام متنوعة تشجع التعاون والعمل بروح الفريق، وتعزز العلاقات الإنسانية الإيجابية داخل المدرسة ومع المجتمع المحلي، مع متابعتها وتقويمها وتطويرها بانتظام.',null,1),
('plan','1-3-1-2',73.25,78,'الفصل الدراسي الأول والثاني',array['المدير / الوكيل','المعلمون','الموجه الطلابي']::text[],'برنامج الشراكة الأسرية لدعم التعلم والاستعداد للمستقبل','[{"t":"لقاءات دورية لشرح تقدم التعلم واحتياجاته"},{"t":"قنوات تواصل منتظمة بمهام ونصائح منزلية"},{"t":"ورش أسرية لمهارات التعلم والعادات الدراسية"},{"t":"مشاركة الأسرة في خطط الدعم الفردية للطلاب"},{"t":"فعاليات مهنية مبكرة لتعريف المتعلمين بالمهن"}]'::jsonb,array['سجل لقاءات الأسرة ومحاضر التواصل والمتابعة','نشرات/رسائل منزلية وخطط دعم موقعة','تقارير فعاليات ومشاركات أسرية موثقة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','حضور أولياء الأمور في اللقاءات ≥ 60%، وتواصل موثق مع أسر 100% من المتعلمين المتعثرين.',null,'المؤشر في مستوى الانطلاق (73.25%) والمستهدف 78% (التقدم). توقعات الهيئة: فرص تواصل فعّال مع الأسرة بأساليب متنوعة لدعم تعلم أبنائهم وتقويم أدائهم وحل مشكلاتهم، وأنشطة مبتكرة للتوعية بدورهم وإشراكهم في التحضير لمستقبل أبنائهم.',null,2),
('plan','1-3-1-3',75,90,'الفصل الدراسي الثاني — متابعة وتطوير',array['المدير / الوكيل','رائد النشاط','منسق الشراكات']::text[],'برنامج الشراكة المجتمعية لدعم التعلم وخدمة المجتمع','[{"t":"حصر الجهات المجتمعية وبناء قاعدة شركاء"},{"t":"توقيع مبادرات مشتركة تخدم تعلم المتعلمين"},{"t":"استضافة مختصين وورش من المجتمع المحلي"},{"t":"تنفيذ زيارات تعليمية تدعم الخبرات الحياتية"},{"t":"قياس أثر الشراكات وتحسينها سنويًا"}]'::jsonb,array['خطة الشراكات وقائمة الجهات ومحاضر التواصل','اتفاقيات/خطابات تعاون وتقارير تنفيذ المبادرات','تقارير أثر الشراكات وصور/سجلات الزيارات']::text[],'فريق التقويم الذاتي','الفصل الدراسي الثاني — متابعة وتطوير','توقيع ≥ 3 شراكات فاعلة موثقة، وتنفيذ ≥ 2 فعاليتين مجتمعيتين في الفصل الدراسي.',null,'المؤشر في مستوى التقدم (75%) ويُستكمل التطوير للوصول إلى التميز (90%). توقعات الهيئة: فرص للتواصل مع المجتمع المحلي بطرق متنوعة، واستثمار إمكانات المؤسسات الوطنية لدعم التعلم وتلبية احتياجات ذوي الإعاقة والموهوبين، وإتاحة إمكانات المدرسة لخدمة المجتمع.',null,3),
('plan','1-4-1-1',66.5,75,'الفصل الدراسي الأول والثاني',array['المدير','الوكيل','المعلمون']::text[],'برنامج دعم الحصول على الرخصة المهنية لمنسوبي المدرسة','[{"t":"حصر المستهدفين وتحديد احتياجاتهم التدريبية"},{"t":"إعداد خطة مذاكرة وجدول مراجعة منتظم"},{"t":"توفير مصادر تدريبية ونماذج اختبارات تجريبية"},{"t":"تنظيم لقاءات دعم ومجموعات تعلم تعاونية"},{"t":"متابعة التقدم وتحفيز المجتازين وتكريمهم"}]'::jsonb,array['قائمة المستهدفين وخطة الدعم المعتمدة','سجلات اللقاءات ومواد التدريب والنماذج','النتائج والشهادات/سجلات التكريم']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','نسبة المعلمين المرخصين ≥ 95%، وخطة دعم موثقة لكل معلم غير مرخص.','هدايا – شهادات تقدير','المؤشر في مستوى الانطلاق (66.5%) والمستهدف 75% (التقدم). توقعات الهيئة: أنشطة وبرامج توعوية تشجع المنسوبين وتحفزهم للمبادرة في الحصول على الرخصة المهنية، ومتابعة تقدمهم المهني وفق الرتب المهنية.',null,4),
('plan','1-5-1-1',82,90,'الفصل الدراسي الثاني — متابعة وتطوير',array['المدير / الوكيل','المعلمون','مسؤول الأمن والسلامة']::text[],'حماية حقوق المتعلمين وتعزيز بيئة آمنة','[{"t":"نشر ثقافة حقوق المتعلمين"},{"t":"توعية المتعلمين بحقوقهم وواجباتهم"},{"t":"متابعة حالات الحماية والرعاية"},{"t":"تطبيق إجراءات الإبلاغ والمعالجة"},{"t":"تعزيز البيئة المدرسية الآمنة والداعمة"}]'::jsonb,array['خطة التوعية بحقوق المتعلمين','سجلات المتابعة والرصد','محاضر لجنة الحماية','برامج توعوية ومواد إرشادية','تقارير الحالات والإجراءات المتخذة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الثاني — متابعة وتطوير','توعية 100% من المتعلمين والمنسوبين بإجراءات الحماية، ومعالجة 100% من البلاغات خلال المدة النظامية.',null,'المؤشر في مستوى التقدم (82%) ويُستكمل التطوير للوصول إلى التميز (90%). توقعات الهيئة: إجراءات معتمدة لحماية المتعلمين والحفاظ على حقوقهم، والتوعية بها، وقنوات إبلاغ آمنة، ومتابعة موثقة للحالات وفق الأدلة التنظيمية.',null,5),
('plan','2-1-1-1',71.5,77,'الفصل الدراسي الأول والثاني',array['المدير / الوكيل','منسق الموهوبين / مسؤول الدمج','المعلمون']::text[],'برنامج التعلم المتمايز والدعم الشامل لجميع المتعلمين','[{"t":"تشخيص احتياجات المتعلمين وتحديد الفروق الفردية"},{"t":"تصميم أنشطة متدرجة تلائم مستويات المتعلمين"},{"t":"تكييف الوسائل والبيئة لذوي الإعاقة"},{"t":"إثراء الموهوبين بمهام تحدٍّ ومشاريع صغيرة"},{"t":"متابعة تقدم فردية وتحديث خطط الدعم"}]'::jsonb,array['نتائج التشخيص وسجلات الفروق الفردية','خطط دروس متمايزة ونماذج تكييف وإثراء','خطط دعم فردية وتقارير متابعة التقدم']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','خطة تعليمية فردية/إثرائية موثقة لـ100% من ذوي الإعاقة والموهوبين، ومتابعة فصلية لتنفيذها.',null,'المؤشر في مستوى الانطلاق (71.5%) والمستهدف 77% (التقدم). توقعات الهيئة: فرص تعلم متكافئة لجميع المتعلمين تستجيب لاحتياجاتهم المختلفة ومنهم ذوو الإعاقة والموهوبون، مع متابعة الالتزام بذلك وتوفير الوصول الشامل لتعلم ثري عالي الجودة.',null,6),
('plan','2-1-1-5',65.5,75,'الفصل الدراسي الأول والثاني',array['المعلمون','الوكيل']::text[],'برنامج التعلم التطبيقي المرتبط بحياة المتعلمين','[{"t":"تصميم أنشطة من مواقف حياتية واقعية"},{"t":"ربط الدروس بمهارات يومية قابلة للتطبيق"},{"t":"تنفيذ تعلم بالمشروعات الصغيرة داخل الصف"},{"t":"توظيف لعب الأدوار والمحاكاة التعليمية"},{"t":"تقويم الأداء بمنتجات تطبيقية بسيطة"}]'::jsonb,array['خطط دروس تتضمن أنشطة حياتية','نماذج منتجات الطلاب وتقارير الأداء','صور/محاضر تنفيذ المشاريع والأنشطة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','نشاط تطبيقي موثق لكل وحدة دراسية، ومشروع تعلم قائم على الحياة لكل فصل في الفصل الدراسي.',null,'المؤشر في مستوى الانطلاق (65.5%) والمستهدف 75% (التقدم). توقعات الهيئة: ربط خبرات المتعلمين بواقع حياتهم، وأنشطة تطبيقية تشجع البحث والتجريب والاستقصاء للوصول إلى المعرفة وتطبيقها في مواقف جديدة.',null,7),
('plan','2-1-1-6',74,79,'الفصل الدراسي الأول والثاني',array['الوكيل','المعلمون']::text[],'تنمية المهارات القرائية والعددية الأساسية','[{"t":"تشخيص مستوى المتعلمين في القراءة والعدد"},{"t":"تنفيذ برامج علاجية للمتعلمين المحتاجين"},{"t":"تنويع الأنشطة القرائية والعددية داخل الحصة"},{"t":"متابعة تقدم المتعلمين بشكل مستمر"},{"t":"تعزيز مشاركة الأسرة في دعم التعلم"}]'::jsonb,array['نتائج الاختبارات التشخيصية','خطط علاجية للمهارات الأساسية','نماذج من الأنشطة القرائية والعددية','سجلات متابعة تقدم المتعلمين','تقارير الشراكة مع الأسرة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','ارتفاع نسبة المتعلمين المتقنين للمهارات الأساسية بنسبة 15% في القياس البعدي مقارنة بالقبلي.','جوائز','المؤشر في مستوى الانطلاق (74%) والمستهدف 79% (التقدم). توقعات الهيئة: تعزيز مهارات القراءة والكتابة والمهارات العددية الأساسية عبر العمليات الصفية وغير الصفية والأنشطة الإثرائية، مع إعطائها الأولوية ضمن خطة مركزة طويلة المدى تُتابع بانتظام.',null,8),
('plan','2-1-1-7',72.5,78,'الفصل الدراسي الأول والثاني',array['المعلمون']::text[],'برنامج تنمية مهارات التفكير والبحث والابتكار','[{"t":"تنفيذ أنشطة تنمي مهارات التفكير"},{"t":"تدريب المتعلمين على البحث والاستقصاء"},{"t":"تشجيع المبادرات والأفكار الابتكارية"},{"t":"توظيف التعلم بالمشروعات وحل المشكلات"},{"t":"عرض أعمال المتعلمين وتحفيزهم"}]'::jsonb,array['خطة تنمية مهارات التفكير والابتكار','نماذج من الأنشطة والمهام','أعمال ومشروعات المتعلمين','سجلات المشاركة في البرامج والمسابقات','تقارير المتابعة والتحفيز']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','تنفيذ ≥ 2 من مشاريع البحث/الابتكار الطلابية في الفصل الدراسي، وتضمين أسئلة التفكير العليا في 100% من الاختبارات.',null,'المؤشر في مستوى الانطلاق (72.5%) والمستهدف 78% (التقدم). توقعات الهيئة: أساليب وأنشطة تستهدف مهارات التحليل والاستنتاج والتقويم والإبداع وحل المشكلات صفيًا وغير صفي، مع أنشطة إثرائية مبتكرة تُقوَّم وتُطوَّر.',null,9),
('plan','3-1-1-1',71.83,77,'الفصل الدراسي الأول والثاني',array['المعلمون','الوكيل','معلم اللغة العربية']::text[],'برنامج رفع نواتج القراءة والاستعداد للاختبارات الوطنية','[{"t":"تشخيص مستوى القراءة وفق مؤشرات الاختبارات الوطنية"},{"t":"تنفيذ روتين يومي للوعي الصوتي والمفردات"},{"t":"تطبيق مجموعات قراءة موجهة حسب المستوى"},{"t":"توفير تدخل علاجي سريع للمتعثرين وإثراء للمتميزين"},{"t":"متابعة أسبوعية للتقدم وتعديل الخطط بناء على النتائج"}]'::jsonb,array['تقارير التشخيص وخطط القراءة الموجهة حسب المستوى','سجلات متابعة أسبوعية وملفات إنجاز/عينات قراءة','نتائج قياسات دورية مقارنة بمحكات الاختبارات الوطنية']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','ارتفاع متوسط المدرسة في القراءة بـ5 نقاط على الأقل عن الدورة السابقة، وتنفيذ برنامج علاجي للمتعلمين دون المستوى.','جوائز','المؤشر في مستوى الانطلاق (71.83%) والمستهدف 77% (التقدم). توقعات الهيئة: رفع نسبة المتعلمين المحققين لمستويات متقدمة في القراءة، وتحليل بيانات الاختبارات الوطنية لتحديد الفجوة بين أداء المدرسة والمستوى الوطني، واتخاذ القرارات بشأن البرامج العلاجية والإثرائية.',null,10),
('plan','3-1-1-2',73.6,79,'الفصل الدراسي الأول والثاني',array['المدير','الوكيل','معلم الرياضيات']::text[],'برنامج رفع نواتج الرياضيات والاستعداد للاختبارات الوطنية','[{"t":"تشخيص مستوى الرياضيات وفق مؤشرات الاختبارات الوطنية"},{"t":"تنفيذ روتين يومي للعدّ والمفاهيم العددية الأساسية"},{"t":"تطبيق محطات تعلم رياضية حسب مستويات المتعلمين"},{"t":"تدخل علاجي سريع للمتعثرين وإثراء للمتميزين"},{"t":"متابعة أسبوعية للتقدم وتحديث خطط الدعم"}]'::jsonb,array['تقارير التشخيص وخطط محطات الرياضيات','سجلات متابعة أسبوعية وعينات أعمال المتعلمين','نتائج قياسات دورية مقارنة بمحكات الاختبارات الوطنية']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','ارتفاع متوسط المدرسة في الرياضيات بـ5 نقاط على الأقل عن الدورة السابقة.','جوائز','المؤشر في مستوى الانطلاق (73.6%) والمستهدف 79% (التقدم). توقعات الهيئة: رفع نسبة المتعلمين المحققين لمستويات متقدمة في الرياضيات، وتحليل بيانات الاختبارات الوطنية وتحديد الفجوة واتخاذ القرارات العلاجية والإثرائية المناسبة.',null,11),
('plan','3-1-1-3',null::numeric,75,'الفصل الدراسي الأول — تأسيس الشواهد وخط الأساس',array['المدير','الوكيل','معلم اللغة العربية']::text[],'برنامج التحسين المستند للبيانات لرفع القراءة مقارنة بالأداء السابق','[{"t":"تحليل نتائج الاختبارات الوطنية السابقة وتحديد الفجوات"},{"t":"تحديد مستهدفات نمو واضحة لكل صف/فصل"},{"t":"تنفيذ تدخلات قراءة موجهة حسب مستويات المتعلمين"},{"t":"تطبيق قياسات قصيرة دورية لمتابعة النمو"},{"t":"مراجعة شهرية للنتائج وتعديل الخطة وفق البيانات"}]'::jsonb,array['تقرير مقارنة النتائج الحالية بالسابق وخط الأساس','سجلات القياسات الدورية وجداول متابعة النمو','خطة التحسين ومحاضر اجتماعات المراجعة والتحديث']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول — تأسيس الشواهد وخط الأساس','تقدم موجب في متوسط القراءة مقارنة بخط الأساس، موثق بتقرير مقارنة رسمي.','جوائز','مؤشر مستحدث في الإصدار الثالث بلا قياس سابق، يُوصى ببناء خط أساس وجمع الشواهد من بداية العام. توقعات الهيئة: تحديد خط الأساس من نتائج الدورة السابقة، ومستهدفات نمو واضحة، وتدخلات موجهة حسب المستويات، وقياسات دورية تُوثَّق وتُقارن بالأداء السابق.',null,12),
('plan','3-1-1-4',null::numeric,75,'الفصل الدراسي الأول — تأسيس الشواهد وخط الأساس',array['المدير','الوكيل','معلم الرياضيات']::text[],'برنامج التحسين المستند للبيانات لرفع الرياضيات مقارنة بالأداء السابق','[{"t":"تحليل نتائج الاختبارات الوطنية السابقة وتحديد الفجوات"},{"t":"تحديد مستهدفات نمو واضحة لكل صف/فصل"},{"t":"تنفيذ تدخلات رياضيات موجهة حسب مستويات المتعلمين"},{"t":"تطبيق قياسات قصيرة دورية لمتابعة النمو"},{"t":"مراجعة شهرية للنتائج وتعديل الخطة وفق البيانات"}]'::jsonb,array['تقرير مقارنة النتائج الحالية بالسابق وخط الأساس','سجلات القياسات الدورية وجداول متابعة النمو','خطة التحسين ومحاضر اجتماعات المراجعة والتحديث']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول — تأسيس الشواهد وخط الأساس','تقدم موجب في متوسط الرياضيات مقارنة بخط الأساس، موثق بتقرير مقارنة رسمي.','جوائز','مؤشر مستحدث في الإصدار الثالث بلا قياس سابق، يُوصى ببناء خط أساس وجمع الشواهد من بداية العام. توقعات الهيئة: تحديد خط الأساس من نتائج الدورة السابقة، ومستهدفات نمو واضحة، وتدخلات موجهة حسب المستويات، وقياسات دورية تُوثَّق وتُقارن بالأداء السابق.',null,13),
('plan','3-2-1-4',72.75,78,'الفصل الدراسي الأول والثاني',array['المدير / الوكيل','المعلمون','رائد النشاط / الموجه الطلابي']::text[],'تعزيز المشاركة المجتمعية والعمل التطوعي','[{"t":"إعداد خطة للأنشطة المجتمعية والتطوعية"},{"t":"إشراك المتعلمين في المبادرات التطوعية"},{"t":"تنفيذ برامج خدمة المجتمع داخل المدرسة وخارجها"},{"t":"تحفيز المتعلمين على المشاركة الفاعلة"},{"t":"توثيق المشاركات وقياس أثرها"}]'::jsonb,array['خطة الأنشطة المجتمعية والتطوعية','سجلات وأسماء المشاركين','صور وتقارير تنفيذ المبادرات','شهادات شكر أو مشاركة','نماذج قياس الأثر والتغذية الراجعة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','مشاركة ≥ 40% من المتعلمين في عمل تطوعي موثق، وتسجيل الساعات التطوعية في المنصة الوطنية.',null,'المؤشر في مستوى الانطلاق (72.75%) والمستهدف 78% (التقدم). توقعات الهيئة: برامج وأنشطة نوعية تحفز المتعلمين على المشاركة في الأعمال التطوعية لخدمة المجتمع، ودعم مشاركاتهم وتوظيف ما تعلموه في حلول مبتكرة تعزز المسؤولية.',null,14),
('plan','3-2-1-5',77.5,90,'الفصل الدراسي الثاني — متابعة وتطوير',array['المدير / الوكيل','الموجه الطلابي','المعلمون']::text[],'برنامج الانضباط الإيجابي وتعزيز السلوك المدرسي','[{"t":"إعداد قواعد صفية مصورة ومعلنة للجميع"},{"t":"تدريب يومي على الروتين والانضباط الذاتي"},{"t":"تعزيز إيجابي فوري للسلوكيات المرغوبة"},{"t":"معالجة المخالفات بخطوات تربوية متدرجة"},{"t":"متابعة سلوكية فردية وخطط دعم قصيرة"}]'::jsonb,array['القواعد الصفية المصورة وخطة الانضباط','سجلات التعزيز والمتابعة السلوكية الفردية','تقارير حالات ومحاضر تطبيق الإجراءات التربوية']::text[],'فريق التقويم الذاتي','الفصل الدراسي الثاني — متابعة وتطوير','انخفاض المخالفات السلوكية المسجلة بنسبة 30%، ونسبة الحضور ≥ 95%.',null,'المؤشر في مستوى التقدم (77.5%) ويُستكمل التطوير للوصول إلى التميز (90%). توقعات الهيئة: متابعة التزام المتعلمين بقواعد السلوك والانضباط عبر برامج وأنشطة متنوعة، وأدلة ومنشورات توجيهية تسهم في اكتساب الانضباط الذاتي والسلوك المسؤول.',null,15),
('plan','4-1-1-1',55.75,75,'الفصل الدراسي الأول',array['المدير / الوكيل','مسؤول الأمن والسلامة','مسؤول الصيانة']::text[],'تهيئة المبنى المدرسي وفق الاشتراطات المعتمدة','[{"t":"حصر مرافق المبنى وخدماته المساندة"},{"t":"متابعة جاهزية الفصول والمرافق التعليمية"},{"t":"التأكد من توفر شروط السلامة والصيانة"},{"t":"متابعة النظافة والتهوية والإضاءة"},{"t":"رصد الاحتياج ورفع طلبات التحسين"}]'::jsonb,array['سجل مرافق المبنى وتجهيزاته','تقارير الصيانة والسلامة','نماذج المتابعة الدورية','صور للمرافق والخدمات المساندة','خطابات وطلبات التحسين']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول','تقرير حالة مبنى موثق ومرفوع للجهة المختصة في الشهر الأول، ومعالجة ≥ 70% من الملاحظات القابلة للمعالجة داخليًا.',null,'المؤشر في مستوى الانطلاق (55.75%) والمستهدف 75% (التقدم). توقعات الهيئة: التحقق من استيفاء المبنى للمواصفات والاشتراطات المعتمدة، ورصد الفجوات ورفعها للجهات المختصة ومتابعة معالجتها، وتوثيق الخدمات المساندة المتوفرة.',null,16),
('plan','4-1-1-2',53.25,75,'الفصل الدراسي الأول',array['المدير','مسؤول الأمن والسلامة','مسؤول الصيانة']::text[],'برنامج تنظيم المبنى والمساحات بما يلائم عدد المتعلمين وخصائصهم العمرية','[{"t":"توزيع الفصول والزوايا وفق كثافة المتعلمين"},{"t":"تخصيص مساحات لعب آمنة تناسب العمر"},{"t":"تنظيم مسارات حركة تقلل الازدحام اليومي"},{"t":"تهيئة أثاث وتجهيزات مناسبة لطول المتعلمين"},{"t":"مراجعة دورية للتنظيم ومعالجة الملاحظات"}]'::jsonb,array['مخطط توزيع الفصول والمساحات المعتمد','تقارير سلامة وملاحظات تنظيم الحركة والازدحام','صور تهيئة الفصول والزوايا وسجلات المتابعة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول','مطابقة متوسط عدد المتعلمين في الفصل للمعيار، وتوفر مسارات ميسرة لذوي الإعاقة بنسبة 100%.',null,'المؤشر في مستوى الانطلاق (53.25%) والمستهدف 75% (التقدم). توقعات الهيئة: العمل مع الجهات ذات العلاقة لتطوير المبنى وتنظيم الأثاث بما يحقق الرفاه للمتعلمين ويراعي خصائص المرحلة العمرية ومتطلبات العملية التعليمية وذوي الإعاقة.',null,17),
('plan','4-1-1-3',57,75,'الفصل الدراسي الأول',array['المدير / الوكيل','مسؤول الأمن والسلامة','مسؤول الصيانة']::text[],'برنامج تهيئة المرافق الداعمة للنمو والتعلم للجميع','[{"t":"حصر احتياجات المتعلمين والمرافق وفق الخصائص"},{"t":"تهيئة مرافق شاملة لذوي الإعاقة داخل المبنى"},{"t":"توفير زوايا تعلم ولعب متعددة داخل الفصول"},{"t":"تجهيز غرف دعم وخدمات مساندة عند الحاجة"},{"t":"متابعة صيانة المرافق وتحديثها وفق الملاحظات"}]'::jsonb,array['خطة تهيئة المرافق وقائمة الاحتياجات المعتمدة','صور للمرافق المهيأة وسجلات الصيانة والتحسين','تقارير متابعة رضا المستفيدين ومحاضر المراجعة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول','جاهزية 100% من المعامل بتجهيزاتها الأساسية، وتفعيلها في ≥ 80% من حصص المواد العلمية.',null,'المؤشر في مستوى الانطلاق (57%) والمستهدف 75% (التقدم). توقعات الهيئة: تنظيم الفصول والمعامل وتجهيزاتها بما يطابق المعايير ويلبي احتياجات المتعلمين وذوي الإعاقة، وتوفير المعامل والوسائل والأدوات والمواد اللازمة لأنشطة التعلم.',null,18),
('plan','4-1-1-4',53.25,75,'الفصل الدراسي الأول',array['المدير','الوكيل','مسؤول الصيانة']::text[],'برنامج تجهيز مصادر تعلم متنوعة وشاملة للجميع','[{"t":"حصر احتياجات مصادر التعلم لكل فئة"},{"t":"توفير وسائل متعددة الحواس داخل الفصول"},{"t":"تجهيز أدوات مساندة لذوي الإعاقة بالتدرج"},{"t":"تفعيل مركز/ركن مصادر تعلم بإعارة منظمة"},{"t":"صيانة وتحديث المصادر وتوثيق استخدامها"}]'::jsonb,array['قوائم الجرد والفواتير ومحاضر الاستلام','صور مصادر التعلم والوسائل المساندة المتوفرة','سجلات الإعارة والاستخدام وتقارير المتابعة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول','رضا المتعلمين عن المرافق ≥ 80% في الاستبانة، ومعالجة 100% من ملاحظات المرافق المرصودة.',null,'المؤشر في مستوى الانطلاق (53.25%) والمستهدف 75% (التقدم). توقعات الهيئة: الاستفادة من التجارب الناجحة في استدامة المرافق والخدمات المساندة وملاءمتها لاحتياجات المتعلمين وتحقيق الرفاه لهم ومنهم ذوو الإعاقة.',null,19),
('plan','4-2-1-1',63.5,75,'الفصل الدراسي الأول',array['المدير','مسؤول الأمن والسلامة','الوكيل']::text[],'برنامج الأمن والسلامة الشامل للفصول والمرافق','[{"t":"إجراء فحص سلامة دوري للفصول والمرافق"},{"t":"تحديث خطة الإخلاء ومسارات الخروج الواضحة"},{"t":"تدريب العاملين والطلاب على إجراءات الطوارئ"},{"t":"صيانة تجهيزات السلامة وإزالة مصادر الخطر"},{"t":"توثيق الحوادث والملاحظات ومعالجتها فورًا"}]'::jsonb,array['تقارير فحص السلامة وسجلات الصيانة','خطة الإخلاء ومحاضر التدريب ونتائج الإخلاء','سجل الحوادث والإجراءات التصحيحية المتخذة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول','اكتمال قائمة فحص الأمن والسلامة بنسبة 100% شهريًا، وتنفيذ تجربتي إخلاء موثقتين في العام.',null,'المؤشر في مستوى الانطلاق (63.5%) والمستهدف 75% (التقدم). توقعات الهيئة: متابعة متطلبات وتجهيزات الأمن والسلامة في الفصول والمرافق بانتظام، وتعزيز ثقافة الأمن والسلامة والتوعية بالمخاطر، ومتابعة سلامة المتعلمين أثناء الدخول والخروج.',null,20),
('plan','4-2-1-2',74,79,'الفصل الدراسي الأول والثاني',array['المدير','مسؤول الصيانة','الوكيل']::text[],'برنامج الصيانة الوقائية الدورية للمرافق والتجهيزات','[{"t":"إعداد خطة صيانة دورية بجدول زمني"},{"t":"تنفيذ جولات تفقد شهرية للمرافق والتجهيزات"},{"t":"استقبال بلاغات الأعطال عبر نموذج موحد"},{"t":"معالجة الأعطال وتوثيق الإصلاحات فورًا"},{"t":"مراجعة تقارير الصيانة وتحسين الخطة"}]'::jsonb,array['خطة الصيانة وسجل الجولات التفقدية','نماذج بلاغات الأعطال وتقارير الإصلاح','محاضر متابعة وتحليل تكرار الأعطال']::text[],'فريق التقويم الذاتي','الفصل الدراسي الأول والثاني','إغلاق ≥ 90% من طلبات الصيانة خلال المدة المحددة، وسجل صيانة دوري موثق.',null,'المؤشر في مستوى الانطلاق (74%) والمستهدف 79% (التقدم). توقعات الهيئة: متابعة الصيانة لجميع المرافق والتجهيزات بانتظام بما يضمن استدامة كفاءة المبنى وفاعليته في تلبية متطلبات العملية التعليمية.',null,21),
('plan','4-2-1-3',78.75,90,'الفصل الدراسي الثاني — متابعة وتطوير',array['المدير','مسؤول الأمن والسلامة','الوكيل']::text[],'برنامج النظافة اليومية والرقابة المستمرة للمبنى','[{"t":"إعداد خطة نظافة يومية بمهام محددة"},{"t":"توزيع مسؤوليات النظافة وفق جدول مناوبات"},{"t":"تعقيم نقاط اللمس والمرافق عالية الاستخدام"},{"t":"متابعة جودة النظافة بجولات رقابية دورية"},{"t":"توثيق الملاحظات ومعالجتها"}]'::jsonb,array['خطة النظافة وجداول المناوبات المعتمدة','سجلات الجولات الرقابية ونماذج الملاحظات','تقارير التعقيم والصور قبل/بعد عند الحاجة']::text[],'فريق التقويم الذاتي','الفصل الدراسي الثاني — متابعة وتطوير','جولات تفقدية يومية موثقة، وتقييم النظافة ≥ 90% في الجولات الأسبوعية.',null,'المؤشر في مستوى التقدم (78.75%) ويُستكمل التطوير للوصول إلى التميز (90%). توقعات الهيئة: متابعة نظافة المبنى ومرافقه بانتظام، وتوفير أدوات النظافة اللازمة وحفظها في أماكن ملائمة.',null,22),
