) as v(kind, code, current, target, semester, team, initiative, methods, evidence, follow, period, measure, needs, rec, owner, sort)
on conflict (plan_id, code) do nothing;

update public.acc_plans set status = 'active', approved_at = coalesce(approved_at, now()) where id = (select id from public.acc_plans where academic_year = coalesce((select value from public.settings where key = 'active_year'), '1448') and status <> 'archived' order by version desc, created_at desc limit 1);

-- للتحقق: يجب أن يظهر 23 برنامجًا و24 للاستدامة
select p.title as "الخطة", p.status as "الحالة",
       count(*) filter (where g.kind = 'plan') as "برامج", count(*) filter (where g.kind = 'sustain') as "استدامة"
  from public.acc_plans p left join public.acc_programs g on g.plan_id = p.id
 where p.id = (select id from public.acc_plans where academic_year = coalesce((select value from public.settings where key = 'active_year'), '1448') and status <> 'archived' order by version desc, created_at desc limit 1) group by p.id;

